#!/bin/bash
# Steppe cavalry and South Asian war elephants (2026-10-13). Mount parts + rider kits, symbolic costumes.
cd "$(git -C "$(dirname "$0")" rev-parse --show-toplevel)"
A=(.venv/bin/python -I tools/asset.py draw)
m1() { "${A[@]}" mount ngua-thao-nguyen --names body,head,front-upper,front-lower,hind-upper,hind-lower,tail,saddle --desc "a small stocky steppe pony, dun-coloured coat with a thick shaggy dark mane and short sturdy legs. Parts: (1) BODY: barrel and chest only, no head, no neck, no legs, no tail; (2) HEAD AND NECK together as one piece with a simple rope bridle, the neck base at the lower left where it joins the shoulders; (3) FRONT UPPER LEG: shoulder to knee; (4) FRONT LOWER LEG: knee to hoof; (5) HIND UPPER LEG: hip and thigh down to the hock; (6) HIND LOWER LEG: hock to hoof; (7) long full TAIL hanging down; (8) SADDLE seen from the side: a high wooden-framed saddle over a thick felt saddle blanket whose cloth is teal, short leather stirrup straps"; }
m2() { "${A[@]}" mount voi-nam-a --names body,head,front-upper,front-lower,hind-upper,hind-lower,tail,saddle --desc "a large South Asian war elephant with grey wrinkled skin, dressed for war. Parts: (1) BODY: barrel and back only, no head, no legs, no tail; (2) HEAD with the ear, long curved tusks and the trunk hanging down, as one piece, wearing a decorative cloth forehead drape whose cloth is teal with small invented geometric trim; (3) FRONT UPPER LEG: shoulder to knee; (4) FRONT LOWER LEG: knee to foot, with a plain bronze anklet; (5) HIND UPPER LEG: hip to knee; (6) HIND LOWER LEG: knee to foot, with a plain bronze anklet; (7) thin TAIL hanging down; (8) SADDLE: a long caparison cloth whose cloth is teal with a light geometric border, draped over the back, with a small wooden riding platform on top that has low rails and a simple fabric canopy on four thin poles"; }
k1() { "${A[@]}" kit thao-nguyen-trung-dai-ky-binh --era trung-dai --region thao-nguyen --role ky-binh --desc "generic medieval steppe nomad horse archer: rounded felt cap with a fur brim, a long wrap-over riding coat whose cloth is teal, closed with a leather belt, loose trousers tucked into soft leather riding boots; the main weapon is a short recurved composite bow drawn vertically, unstrung shape not needed, with its string; instead of a shield draw a leather bow-case-and-quiver of arrows"; }
k2() { "${A[@]}" kit nam-a-co-dai-quan-tuong --era co-dai --region nam-a --role ky-binh --desc "generic ancient South Asian war-elephant warrior: a wrapped cloth turban whose cloth is teal, bare chest with a cloth sash whose cloth is teal across one shoulder, a knee-length wrapped lower garment of undyed cloth, simple metal armbands, bare feet; a long spear with a broad iron blade drawn vertically; a small round hide shield painted teal with a simple invented geometric emblem"; }
mkdir -p library/logs
for f in m1 m2 k1 k2; do $f > library/logs/sa-$f.log 2>&1 & done
wait
grep -h -E "^saved|did not|still not|grid" library/logs/sa-{m1,m2,k1,k2}.log
